import "../register.js";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { after, describe, it } from "node:test";
import {
  applyAddPlan,
  checkProject,
  computeOutdated,
  PACKAGE_ROOT,
  parseProjectManifest,
  planAddRecipes,
} from "@zealakit/core/internal";
import { validateJsonSchema } from "../helpers/json-schema.js";

/**
 * Upgrade contract: projects generated by earlier betas keep working with
 * `add`, `doctor` and `outdated`. The fixtures are real `create` outputs
 * committed under tests/fixtures/projects/ and must never be regenerated
 * casually — they stand in for projects already in users' hands.
 */

const FIXTURES = path.join(PACKAGE_ROOT, "tests/fixtures/projects");
const workRoot = fs.mkdtempSync(path.join(os.tmpdir(), "zealakit-fixtures-"));
after(() => fs.rmSync(workRoot, { recursive: true, force: true }));

const manifestSchema = JSON.parse(
  fs.readFileSync(path.join(PACKAGE_ROOT, "schema/zealakit.schema.json"), "utf-8"),
);

function copyFixture(name: string): string {
  const target = path.join(workRoot, `${name}-${Math.random().toString(36).slice(2, 8)}`);
  fs.cpSync(path.join(FIXTURES, name), target, { recursive: true, verbatimSymlinks: true });
  return target;
}

const fixtures = fs.readdirSync(FIXTURES).filter((name) => name.endsWith("-beta4"));

describe("beta.4 project fixtures", () => {
  it("has fixtures", () => {
    assert.ok(fixtures.length >= 2);
  });

  for (const name of fixtures) {
    describe(name, () => {
      it("zealakit.json parses and matches the shipped schema", () => {
        const raw = JSON.parse(
          fs.readFileSync(path.join(FIXTURES, name, "zealakit.json"), "utf-8"),
        );
        assert.deepEqual(validateJsonSchema(raw, manifestSchema), []);
        assert.equal(parseProjectManifest(raw).ok, true);
      });

      it("doctor finds no failures", () => {
        const report = checkProject(copyFixture(name));
        assert.equal(report.isZealakitProject, true);
        assert.deepEqual(
          report.checks.filter((check) => check.status === "fail"),
          [],
        );
      });

      it("outdated runs without blockers", () => {
        assert.deepEqual(computeOutdated(copyFixture(name)).blockers, []);
      });
    });
  }

  it("add works on the Node fixture", () => {
    const dir = copyFixture("vite-react-beta4");
    const plan = planAddRecipes(dir, ["zustand"]);
    assert.deepEqual(plan.blockers, []);
    assert.ok(plan.changes.some((change) => change.path === "src/stores/something.store.ts"));
    applyAddPlan(plan);
    assert.ok(fs.existsSync(path.join(dir, "src/stores/something.store.ts")));
  });

  it("add works on the Go fixture", () => {
    const dir = copyFixture("stdlib-api-beta4");
    const plan = planAddRecipes(dir, ["docker-go"]);
    assert.deepEqual(plan.blockers, []);
    assert.ok(plan.changes.some((change) => change.path === "Dockerfile"));
  });
});
